"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Original-frame yield response and non-obligated traffic at a signed junction.

Immediate hazard and cautious proceeding remain judgments, not numeric tests.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon
from yield_reference import inspect as inspect_reference


REQUIRED=("intersection_context.json","entry_history.jsonl","video_frames.jsonl",
          "site_review.json","overview.mkv","approach.mkv",
          "reference_corner.mkv","driver_reference.mkv")


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _inside(vertices,polygon):
    if not isinstance(vertices,list) or len(vertices)<4:raise ValueError("Missing complete vehicle body")
    body=MultiPoint([(_number(v[0],"body x"),_number(v[1],"body y")) for v in vertices]).convex_hull
    return body.intersects(polygon)


def _center(vertices):
    if not isinstance(vertices,list) or len(vertices)<4:
        raise ValueError("Missing complete vehicle body")
    return [sum(_number(point[axis],"body coordinate") for point in vertices)/len(vertices)
            for axis in (0,1)]


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"intersection_context.json").read_text())
    for key in ("native_map_id","intersection_id","ego_approach_road_id",
                "other_approach_road_id","native_yield_sign_id","sign_governance_source",
                "entrance_inventory_source","yield_reference_source","highway_status_source"):
        if ctx.get(key) is None:raise ValueError("Missing sourced intersection context: "+key)
    if ctx.get("non_through_highway") is not True:
        raise ValueError("Non-through-highway status not sourced")
    officer_case=str(ctx.get("case_id","")).endswith("__officer_control_exception")
    if ctx.get("traffic_signal_control") is not False or ctx.get("police_control") is not officer_case:
        raise ValueError("Officer/signal exception state differs from exact case")
    if ctx.get("ego_entrance_device")!="yield":raise ValueError("Ego yield-sign governance missing")
    reference=inspect_reference(root,ctx)
    entrances=ctx.get("entrances")
    road_ids=ctx.get("entrance_road_ids")
    if (not isinstance(road_ids,list) or len(road_ids)<2 or len(set(road_ids))!=len(road_ids)
            or not isinstance(entrances,list) or len(entrances)!=len(road_ids)
            or any("road_id" not in e or e.get("device") not in ("stop","yield","none") for e in entrances)
            or {e["road_id"] for e in entrances}!=set(road_ids)):
        raise ValueError("Incomplete entrance device inventory")
    own=[e for e in entrances if e["road_id"]==ctx["ego_approach_road_id"]]
    other=[e for e in entrances if e["road_id"]==ctx["other_approach_road_id"]]
    if len(own)!=1 or own[0]["device"]!="yield" or len(other)!=1:
        raise ValueError("Entrance obligation identities unresolved")
    polygon=Polygon(ctx.get("intersection_polygon_xy_m",[]))
    if not polygon.is_valid or polygon.area<=0:raise ValueError("Invalid intersection polygon")
    rows,frames=_rows(root/"entry_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<3 or len(rows)!=len(frames):raise ValueError("Incomplete entry history")
    officer_source=None
    if officer_case:
        officer_path=root/"officer_review.json"
        if not officer_path.is_file():raise ValueError("Missing original officer-control review")
        officer=json.loads(officer_path.read_text())
        if (officer.get("intersection_context_sha256")!=hashes["intersection_context.json"]
                or officer.get("camera_sha256")!={name:hashes[name+".mkv"] for name in ("overview","approach","reference_corner","driver_reference")}
                or officer.get("reviewed_carla_frames")!=[row.get("carla_frame") for row in frames]
                or type(officer.get("officer_actor_id")) is not int
                or officer.get("control_observed_at_entry") is not True
                or officer.get("authority_judgment")!="unresolved"):
            raise ValueError("Officer exception lacks complete original-source control review")
        officer_source=hashlib.sha256(officer_path.read_bytes()).hexdigest()
        hashes["officer_review.json"]=officer_source
    previous=(-1,-math.inf);samples=[];first_entry=None
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original frame join failed")
        camera_ids=frame.get("camera_frame_ids")
        if (not isinstance(camera_ids,dict) or set(camera_ids)!={"overview","approach","reference_corner","driver_reference"}
                or any(type(value) is not int or value!=fid for value in camera_ids.values())):
            raise ValueError("Original four-camera frame join failed")
        if row.get("ego_road_id")!=ctx["ego_approach_road_id"] or row.get("yield_sign_id")!=ctx["native_yield_sign_id"]:
            raise ValueError("Ego approach/sign identity mismatch")
        speed=_number(row.get("ego_speed_mps"),"ego speed")
        if speed<0:raise ValueError("Negative speed")
        before=row.get("ego_body_before_yield_reference")
        if type(before) is not bool:raise ValueError("Missing yield-reference body position")
        ego_inside=_inside(row.get("ego_body_vertices_xy_m"),polygon)
        other_inside=_inside(row.get("other_body_vertices_xy_m"),polygon)
        if i==0 and ego_inside:raise ValueError("No pre-entry approach")
        if ego_inside and first_entry is None:first_entry={"frame":fid,"time_s":time}
        samples.append({"frame":fid,"time_s":time,"ego_speed_mps":speed,
                        "ego_body_before_yield_reference":before,
                        "ego_body_in_intersection":ego_inside,
                        "other_body_in_intersection":other_inside,
                        "other_body_center_xy_m":_center(row["other_body_vertices_xy_m"])})
    if first_entry is None:raise ValueError("No observed ego entry")
    prior=[s for s in samples if s["time_s"]<first_entry["time_s"]]
    before_speeds=[s["ego_speed_mps"] for s in prior if s["ego_body_before_yield_reference"]]
    slowed=bool(len(before_speeds)>=2 and min(before_speeds)<before_speeds[0])
    center=polygon.centroid
    for index,sample in enumerate(samples):
        point=sample["other_body_center_xy_m"]
        distance=math.hypot(point[0]-center.x,point[1]-center.y)
        sample["other_distance_to_intersection_center_m"]=distance
        if index:
            elapsed=sample["time_s"]-samples[index-1]["time_s"]
            former=samples[index-1]["other_body_center_xy_m"]
            old_distance=samples[index-1]["other_distance_to_intersection_center_m"]
            sample["other_center_speed_mps"]=math.hypot(point[0]-former[0],point[1]-former[1])/elapsed
            sample["other_center_closing_mps"]=(old_distance-distance)/elapsed
        else:
            sample["other_center_speed_mps"]=None
            sample["other_center_closing_mps"]=None
    return {"format":"worker-yield-sign-intersection-observations","sources":hashes,
            "native_yield_sign_id":ctx["native_yield_sign_id"],
            "non_through_highway":ctx["non_through_highway"],
            "first_ego_entry":first_entry,"observed_slowed_or_stopped_before_reference":slowed,
            "other_entrance_device":other[0]["device"],
            "other_not_obligated_by_stop_or_yield":other[0]["device"] not in ("stop","yield"),
            "other_inside_at_ego_entry":next(s["other_body_in_intersection"] for s in samples if s["frame"]==first_entry["frame"]),
            "officer_control_observed":officer_case,
            "officer_control_source_sha256":officer_source,
            "subsection_one_reference":reference,
            "samples":samples,"immediate_hazard_judgment":"unresolved",
            "caution_and_yield_judgment":"unresolved","legal_conclusion":"unresolved"}

"""Pre-tick vehicle commands for the staged signed-entrance traffic pair."""

import math

from yield_capture import _vertices


def _speed(actor):
    velocity = actor.get_velocity()
    values = (velocity.x, velocity.y, velocity.z)
    if any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in values):
        raise ValueError("Missing finite Native actor velocity")
    return math.sqrt(sum(v * v for v in values))


def _control(target, observed):
    delta = (target - observed) * .25
    return {"throttle": min(1.0, max(0.0, delta)),
            "brake": min(1.0, max(0.0, -delta)), "steer": 0.0}


def apply_motion(world, staging, tick, *, control_factory=None):
    """Use current Native bodies; actual response is measured after the tick."""
    if control_factory is None:
        import carla
        control_factory = carla.VehicleControl
    ego, other, stage = staging["ego"], staging["other"], staging["stage"]
    origin, forward = staging["reference_origin_xy_m"], staging["ego_forward_xy"]
    ego_point = ego.get_location()
    other_point = other.get_location()
    ego_waypoint = world.get_map().get_waypoint(ego_point, project_to_road=False)
    other_waypoint = world.get_map().get_waypoint(other_point, project_to_road=False)
    if (ego_waypoint is None or ego_waypoint.road_id not in (158208, 158210, 158211)
            or other_waypoint is None or other_waypoint.road_id not in (158212, 158213, 158214)):
        raise ValueError("Native actor left the connected signed-intersection routes")
    before = all(sum((point[i] - origin[i]) * forward[i] for i in (0, 1)) < 0
                 for point in _vertices(ego))
    other_clear = other_point.y <= -12.0
    ego_target = 0.0 if ego_point.x >= 55.0 else stage.target_ego_speed(
        before_reference=before, other_body_clear=other_clear)
    other_target = 0.0 if other_point.y <= -55.0 else stage.target_other_speed(tick)
    ego_command, other_command = _control(ego_target, _speed(ego)), _control(other_target, _speed(other))
    ego.apply_control(control_factory(**ego_command))
    other.apply_control(control_factory(**other_command))
    return {"ego_target_mps": ego_target, "other_target_mps": other_target,
            "ego_before_reference": before, "other_clear_by_position": other_clear,
            "ego_command": ego_command, "other_command": other_command}

"""Find a Native yield-sign actor whose trigger contains the approach point.

This tests physical sign governance. Official status and properly erected face
still need Native map and original-camera review.
"""


def find_governing_yield_sign(world, approach_waypoint):
    point = approach_waypoint.transform.location
    matches = []
    for sign in world.get_actors().filter("traffic.yield*"):
        if sign.trigger_volume.contains(point, sign.get_transform()):
            matches.append(sign)
    if len(matches) != 1:
        raise ValueError(f"Expected one governing yield sign, found {len(matches)}")
    return matches[0]

"""Exact C158208 signed-entrance construction knobs for Native staging.

These are engineering targets and spawn points, never legal hazard thresholds.
Observed bodies and speed from yield_capture.py determine what happened.
"""

from dataclasses import dataclass
import math

PREFIX = "testing__C158208__NRS-484B-257-2__motor_vehicle_driver__"
KINDS = ("yield_other_inside", "yield_other_approaching", "yield_other_obligated",
         "yield_no_slow", "officer_control_exception")


@dataclass(frozen=True)
class Stage:
    case_id: str
    other_release_tick: int = 0
    approach_speed_mps: float = 8.0
    reference_speed_mps: float = 2.0

    def __post_init__(self):
        if self.case_id not in {PREFIX + kind for kind in KINDS}:
            raise ValueError("Unknown exact signed-entrance case")
        if type(self.other_release_tick) is not int or self.other_release_tick < 0:
            raise ValueError("Invalid other-vehicle release tick")
        if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) or v <= 0
               for v in (self.approach_speed_mps, self.reference_speed_mps)):
            raise ValueError("Invalid engineering speed target")
        if self.kind != "yield_no_slow" and self.reference_speed_mps >= self.approach_speed_mps:
            raise ValueError("Yield-response construction needs lower reference target")

    @property
    def kind(self):
        return self.case_id.removeprefix(PREFIX)

    @property
    def other_stop_sign(self):
        return self.kind == "yield_other_obligated"

    @property
    def officer_control_source_required(self):
        return self.kind == "officer_control_exception"

    @property
    def other_start_xy_m(self):
        # CARLA coordinates: south approach advances from positive Y toward 0.
        return (1.8, -4.0) if self.kind != "yield_other_approaching" else (1.8, 25.0)

    def target_ego_speed(self, *, before_reference, other_body_clear):
        if type(before_reference) is not bool or type(other_body_clear) is not bool:
            raise ValueError("Missing observed reference/other-body state")
        if self.kind == "yield_no_slow":
            return self.approach_speed_mps
        if before_reference and not other_body_clear:
            return self.reference_speed_mps
        return self.approach_speed_mps

    def target_other_speed(self, tick):
        if type(tick) is not int or tick < 0:
            raise ValueError("Missing Native tick index")
        return 0.0 if tick < self.other_release_tick else 5.0


def primary(case_id):
    kind = case_id.removeprefix(PREFIX)
    return Stage(case_id, other_release_tick=80 if kind == "yield_other_approaching" else 150)

"""Saved-only signed-entrance measurements from original joined source frames."""

import argparse
import hashlib
import json
from pathlib import Path

from yield_entry_measurements import analyze
from yield_stage import KINDS, PREFIX

CAMERAS = ("overview.mkv", "approach.mkv", "reference_corner.mkv", "driver_reference.mkv")

MEASUREMENT_INPUTS = {
    "signed_entrance": ("intersection_context.json", "site_review.json", "video_frames.jsonl", *CAMERAS),
    "entry_reference": ("intersection_context.json", "site_review.json", "video_frames.jsonl", *CAMERAS),
    "initial_yield_response": ("entry_history.jsonl", "video_frames.jsonl", "site_review.json"),
    "other_entrance_obligation": ("intersection_context.json", "entry_history.jsonl", "video_frames.jsonl"),
    "other_crossing_relation": ("entry_history.jsonl", "video_frames.jsonl", "intersection_context.json"),
    "control_exception": ("intersection_context.json", "site_review.json", "video_frames.jsonl", *CAMERAS),
}


def measure_signed_entrance(report):
    return {"non_through_highway": report["non_through_highway"],
            "yield_sign_id": report["native_yield_sign_id"]}


def measure_entry_reference(report):
    return report["subsection_one_reference"]


def measure_initial_yield_response(report):
    return {"first_entry": report["first_ego_entry"],
            "slowed_or_stopped_before_reference": report["observed_slowed_or_stopped_before_reference"]}


def measure_other_entrance_obligation(report):
    return {"device": report["other_entrance_device"],
            "not_obligated_by_stop_or_yield": report["other_not_obligated_by_stop_or_yield"]}


def measure_other_crossing_relation(report):
    return {"inside_at_ego_entry": report["other_inside_at_ego_entry"],
            "samples": [{"frame": row["frame"], "time_s": row["time_s"],
                         "inside": row["other_body_in_intersection"],
                         "closing_mps": row["other_center_closing_mps"]}
                        for row in report["samples"]]}


def measure_control_exception(report):
    return {"officer_control_observed": report["officer_control_observed"],
            "officer_source_sha256": report["officer_control_source_sha256"],
            "authority_judgment": "unresolved", "signal_control": False}


def bound_measurements(report):
    methods = {
        "signed_entrance": measure_signed_entrance,
        "entry_reference": measure_entry_reference,
        "initial_yield_response": measure_initial_yield_response,
        "other_entrance_obligation": measure_other_entrance_obligation,
        "other_crossing_relation": measure_other_crossing_relation,
        "control_exception": measure_control_exception,
    }
    values = {key: {"value": method(report), "method": method.__name__,
                    "sources": {name: report["sources"][name] for name in MEASUREMENT_INPUTS[key]}}
              for key, method in methods.items()}
    if report["officer_control_observed"]:
        name = "officer_review.json"
        values["control_exception"]["sources"][name] = report["sources"][name]
    return values


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _target(case_id, report):
    kind = case_id.removeprefix(PREFIX)
    if kind not in KINDS:
        raise ValueError("Wrong exact signed-entrance case")
    if kind == "yield_other_inside":
        name, requested, measured = "other_body_inside_at_ego_entry", True, report["other_inside_at_ego_entry"]
    elif kind == "yield_other_approaching":
        before = [sample for sample in report["samples"]
                  if sample["time_s"] <= report["first_ego_entry"]["time_s"]]
        name, requested = "other_center_closing_before_ego_entry", True
        measured = any(sample["other_center_closing_mps"] is not None
                       and sample["other_center_closing_mps"] > 0 for sample in before)
    elif kind == "yield_other_obligated":
        name, requested, measured = ("other_stop_or_yield_obligation", True,
                                     not report["other_not_obligated_by_stop_or_yield"])
    elif kind == "yield_no_slow":
        name, requested, measured = ("no_observed_pre_reference_slowing", True,
                                     not report["observed_slowed_or_stopped_before_reference"])
    else:
        name, requested, measured = "originally_reviewed_officer_control", True, report["officer_control_observed"]
    return {"target": name, "requested": requested, "measured": measured,
            "method": "original_source_joined_saved_measurement",
            "tolerance": 0, "matched": requested == measured,
            "physical_cause_confirmed": False,
            "cause_evidence": ["entry_history.jsonl", "video_frames.jsonl",
                               "intersection_context.json", "site_review.json"]}


def build_result(attempt, config, report):
    attempt = Path(attempt)
    case_id = config.get("selected_case_id")
    target = _target(case_id, report)
    samples = report["samples"]
    channels = {
        "ego_speed_mps": [row["ego_speed_mps"] for row in samples],
        "ego_body_in_intersection": [int(row["ego_body_in_intersection"]) for row in samples],
        "other_body_in_intersection": [int(row["other_body_in_intersection"]) for row in samples],
        "other_distance_to_intersection_center_m": [row["other_distance_to_intersection_center_m"] for row in samples],
        "other_center_closing_mps": [row["other_center_closing_mps"] if row["other_center_closing_mps"] is not None else 0.0 for row in samples],
        "other_center_closing_valid": [int(row["other_center_closing_mps"] is not None) for row in samples],
        "ego_before_yield_reference": [int(row["ego_body_before_yield_reference"]) for row in samples],
    }
    units = {"ego_speed_mps": "m/s", "ego_body_in_intersection": "count",
             "other_body_in_intersection": "count",
             "other_distance_to_intersection_center_m": "m",
             "other_center_closing_mps": "m/s", "other_center_closing_valid": "count",
             "ego_before_yield_reference": "count"}
    evidence = [{"name": name, "unit": units[name],
                 "reference": "channels/" + name + ".jsonl"} for name in channels]
    for name in ("signed_intersection_status_and_all_entrances", "site_and_officer_review"):
        evidence.append({"name": name, "unit": "structured record",
                         "reference": "channels/" + name + ".json"})
    result = {"case_id": case_id,
              "measured_values": {"first_ego_entry": report["first_ego_entry"],
                                  "observed_slowed_or_stopped_before_reference": report["observed_slowed_or_stopped_before_reference"],
                                  "other_inside_at_ego_entry": report["other_inside_at_ego_entry"],
                                  "other_not_obligated_by_stop_or_yield": report["other_not_obligated_by_stop_or_yield"],
                                  "officer_control_observed": report["officer_control_observed"]},
              "target_checks": [target], "setup_confirmed": False,
              "behavior_attempted": False, "maneuver_completed": False,
              "termination_reason": "Saved source analysis; independent physical audit pending",
              "physical_failure_flags": ["Native and original-pixel physical review pending"],
              "trace_reference": "trace.jsonl", "video_references": list(CAMERAS),
              "video_frame_map_reference": "video_frames.jsonl",
              "recording_description": config["recording_description"],
              "recording_evidence": evidence,
              "source_evidence_hashes": report["sources"],
              "capture_evidence_sha256": _sha(attempt / "capture/evidence.jsonl"),
              "realized_observables": {}}
    return result, channels


def finalize(attempt, output):
    attempt, output = Path(attempt), Path(output)
    if output.exists() or (attempt / "result.json").exists() or (attempt / "channels").exists():
        raise ValueError("Retain previous saved finalization; use a fresh attempt")
    for name in ("config.json", "trace.jsonl", "capture/evidence.jsonl",
                 "intersection_context.json", "entry_history.jsonl",
                 "video_frames.jsonl", "site_review.json", *CAMERAS):
        if not (attempt / name).is_file():
            raise ValueError("Missing required source: " + name)
    config = json.loads((attempt / "config.json").read_text())
    report = analyze(attempt)
    result, values = build_result(attempt, config, report)
    channels = attempt / "channels"
    channels.mkdir()
    for name, series in values.items():
        with (channels / (name + ".jsonl")).open("x") as stream:
            for row, value in zip(report["samples"], series):
                stream.write(json.dumps({"original_frame": row["frame"],
                                         "time_s": row["time_s"], "value": value},
                                        allow_nan=False) + "\n")
    status = {"signed_intersection_status_and_all_entrances": {
        "non_through_highway": report["non_through_highway"],
        "native_yield_sign_id": report["native_yield_sign_id"],
        "other_entrance_device": report["other_entrance_device"],
        "other_not_obligated_by_stop_or_yield": report["other_not_obligated_by_stop_or_yield"],
        "source_sha256": report["sources"]["intersection_context.json"]}}
    review = {"site_and_officer_review": {"subsection_one_reference": report["subsection_one_reference"],
        "officer_control_observed": report["officer_control_observed"],
        "officer_source_sha256": report["officer_control_source_sha256"],
        "closing_rate_first_frame_valid": False,
        "immediate_hazard_judgment": "unresolved", "caution_and_yield_judgment": "unresolved",
        "proper_sign_judgment": "unresolved", "legal_conclusion": "unresolved"}}
    for name, context in (("signed_intersection_status_and_all_entrances", status),
                          ("site_and_officer_review", review)):
        (channels / (name + ".json")).write_text(json.dumps(context, indent=2) + "\n")
    from worker_exchange.native_output import physical_result, write_result
    result = physical_result(attempt, result)
    write_result(attempt, result)
    output.write_text(json.dumps({"format": "worker-c158208-signed-entrance-analysis",
                                  "case_id": config["selected_case_id"],
                                  "measurements": bound_measurements(report),
                                  "raw_observations": report,
                                  "physical_checks": result["physical_checks"],
                                  "legal_conclusion": "unresolved",
                                  "analysis_complete": True},
                                 indent=2, allow_nan=False) + "\n")
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    finalize(args.attempt, args.output)


if __name__ == "__main__":
    main()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from yield_construction import stage_case
from yield_stage import PREFIX, primary


class Actors:
    def __init__(self, other_stop):
        self.other_stop = other_stop

    def filter(self, pattern):
        if pattern == "traffic.stop*" and not self.other_stop:
            return []
        return [NS(id=90 if pattern == "traffic.stop*" else 88,
                   trigger_volume=NS(contains=lambda point, transform: True),
                   get_transform=lambda: None)]


class World:
    def __init__(self, other_stop=False):
        self.actors = Actors(other_stop)
        self.destroyed = []
        self.spawned = []
        self.probes = {(-20, 1.8): (158208, -1, False),
                       (0, 1.8): (158210, -1, True),
                       (1.8, 20): (158212, -1, False),
                       (1.8, 0): (158213, -1, True),
                       (-1.8, -20): (158214, 1, False),
                       (-60, 1.8): (158208, -1, False),
                       (1.8, -4): (158213, -1, True),
                       (1.8, 25): (158212, -1, False)}

    def get_map(self):
        return NS(name="signed-map", get_waypoint=self.get_waypoint)

    def get_waypoint(self, location, project_to_road=False):
        road, lane, junction = self.probes[(location.x, location.y)]
        return NS(road_id=road, lane_id=lane, is_junction=junction,
                  transform=NS(location=location))

    def get_actors(self):
        return self.actors

    def get_blueprint_library(self):
        return NS(find=lambda blueprint: blueprint)

    def try_spawn_actor(self, blueprint, transform):
        actor = NS(id=len(self.spawned) + 1, type_id=blueprint,
                   get_location=lambda: transform.location,
                   destroy=lambda: self.destroyed.append(transform.location))
        self.spawned.append(actor)
        return actor


class ConstructionTests(unittest.TestCase):
    location = staticmethod(lambda x, y, z: NS(x=x, y=y, z=z))

    def test_inside_approaching_and_obligated_spawn_on_different_native_lanes(self):
        for kind, other_stop, expected_road in (("yield_other_inside", False, 158213),
                                                ("yield_other_approaching", False, 158212),
                                                ("yield_other_obligated", True, 158213)):
            world = World(other_stop)
            with stage_case(world, primary(PREFIX + kind), location_factory=self.location) as actors:
                self.assertEqual(len(world.spawned), 2)
                self.assertEqual(world.get_waypoint(actors["other"].get_location()).road_id, expected_road)
                self.assertEqual(actors["site"]["native_other_stop_sign_id"], 90 if other_stop else None)
            self.assertEqual(len(world.destroyed), 2)

    def test_officer_case_refuses_unsourced_actor_and_cleans_up(self):
        world = World()
        with self.assertRaisesRegex(ValueError, "sourced Native officer"):
            with stage_case(world, primary(PREFIX + "officer_control_exception"),
                            location_factory=self.location):
                pass
        self.assertEqual(len(world.destroyed), 2)


if __name__ == "__main__":
    unittest.main()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from yield_motion import apply_motion
from yield_stage import PREFIX, primary


class Vehicle:
    def __init__(self, x, y):
        self.point = NS(x=x, y=y, z=.25)
        self.bounding_box = NS(get_world_vertices=self.vertices)
        self.control = None

    def vertices(self, transform):
        return [NS(x=self.point.x + dx, y=self.point.y + dy, z=z)
                for dx, dy in ((-1,-1),(-1,1),(1,1),(1,-1)) for z in (0,1)]

    def get_transform(self):
        return None

    def get_location(self):
        return self.point

    def get_velocity(self):
        return NS(x=0, y=0, z=0)

    def apply_control(self, control):
        self.control = control


class MotionTests(unittest.TestCase):
    def world(self):
        def waypoint(point, project_to_road=False):
            road = 158208 if point.x < 0 else 158212
            return NS(road_id=road)
        return NS(get_map=lambda: NS(get_waypoint=waypoint))

    def test_other_occupancy_and_no_slow_targets_are_distinct(self):
        ego, other = Vehicle(-12, 1.8), Vehicle(1.8, -4)
        staging = {"ego": ego, "other": other, "stage": primary(PREFIX + "yield_other_inside"),
                   "reference_origin_xy_m": [-9, 1.8], "ego_forward_xy": [1, 0]}
        control = lambda **kwargs: kwargs
        command = apply_motion(self.world(), staging, 100, control_factory=control)
        self.assertEqual(command["ego_target_mps"], 2)
        self.assertEqual(command["other_target_mps"], 0)
        self.assertEqual(other.control["brake"], 0)
        staging["stage"] = primary(PREFIX + "yield_no_slow")
        self.assertEqual(apply_motion(self.world(), staging, 100,
                                      control_factory=control)["ego_target_mps"], 8)


if __name__ == "__main__":
    unittest.main()
